/* Original modal score, plucked string model and layered material sounds. */
(()=>{
'use strict';
const A=window.KingdomArt;let context,fxBus,musicBus,noiseBuffer,muted=false,musicEnabled=true,paused=false,fxVolume=.55,musicVolume=.10,nextNote=0,step=0,duckUntil=0,timer=null,lastUnlock=0;const recent={},cache=new Map();
function init(){if(context&&context.state!=='closed')return;try{if(window.navigator?.audioSession)window.navigator.audioSession.type='playback'}catch{}context=new(window.AudioContext||window.webkitAudioContext)();const compressor=context.createDynamicsCompressor();compressor.threshold.value=-19;compressor.knee.value=20;compressor.ratio.value=5;compressor.connect(context.destination);fxBus=context.createGain();musicBus=context.createGain();fxBus.connect(compressor);musicBus.connect(compressor);const delay=context.createDelay(1),echo=context.createGain();delay.delayTime.value=.19;echo.gain.value=.12;musicBus.connect(delay);delay.connect(echo);echo.connect(compressor);noiseBuffer=context.createBuffer(1,context.sampleRate,context.sampleRate);const data=noiseBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;levels();nextNote=context.currentTime+.08;timer=setInterval(schedule,120)}
function levels(){if(!context)return;const t=context.currentTime;fxBus.gain.setTargetAtTime(muted||document.hidden?0:fxVolume,t,.035);musicBus.gain.setTargetAtTime(!musicEnabled||document.hidden?0:musicVolume*(paused?.22:1)*(context.currentTime<duckUntil?.4:1),t,.2)}
function unlock(){try{init();if(context.state!=='running')context.resume().then(()=>{nextNote=context.currentTime+.04;levels();schedule()}).catch(()=>{});if(context.currentTime-lastUnlock>.3||context.currentTime===0){lastUnlock=context.currentTime;const b=context.createBufferSource();b.buffer=context.createBuffer(1,1,context.sampleRate);b.connect(context.destination);b.start(context.currentTime);b.onended=()=>b.disconnect()}levels();schedule()}catch{}}
A.audioStart=unlock;
A.audioRecover=()=>{if(context&&context.state!=='running'){try{context.close()?.catch(()=>{})}catch{}context=null;if(timer!==null)clearInterval(timer);cache.clear();nextNote=0}muted=false;unlock();levels()};
for(const name of ['pointerdown','touchend','keydown'])document.addEventListener(name,unlock,{capture:true,passive:true});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&context){if(context.state!=='running')context.resume().catch(()=>{});nextNote=context.currentTime+.1;levels()}});
A.toggleSound=()=>{muted=!muted;A.audioStart();levels();return !muted};A.audioPause=v=>{paused=v;levels()};
A.setAudio=o=>{if(o.fx!==undefined)fxVolume=o.fx;if(o.music!==undefined)musicVolume=o.music;if(o.musicEnabled!==undefined)musicEnabled=o.musicEnabled;A.audioStart();levels();try{localStorage.setItem('kingdom-audio-v3',JSON.stringify({fx:fxVolume,music:musicVolume,musicEnabled}))}catch{}};
A.audioStatus=()=>({state:context?.state||'waiting-for-gesture',muted,musicEnabled,fx:fxVolume,music:musicVolume,events:Object.keys(recent).length,scoreStep:step,voicesCached:cache.size});
try{const o=JSON.parse(localStorage.getItem('kingdom-audio-v3'));if(o){fxVolume=Math.min(1,Math.max(0,o.fx??.55));musicVolume=Math.min(.7,Math.max(0,o.music??.10));musicEnabled=o.musicEnabled!==false}}catch{}document.addEventListener('visibilitychange',levels);
function envelope(src,at,duration,volume,pan=0,bus=fxBus,attack=.004){const gain=context.createGain(),nodes=[src,gain];gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(Math.max(.0002,volume),at+attack);gain.gain.exponentialRampToValueAtTime(.0001,at+duration);src.connect(gain);if(context.createStereoPanner){const p=context.createStereoPanner();p.pan.value=Math.max(-.85,Math.min(.85,pan));gain.connect(p);p.connect(bus);nodes.push(p)}else gain.connect(bus);src.onended=()=>nodes.forEach(n=>{try{n.disconnect()}catch{}});src.start(at);src.stop(at+duration+.03)}
function tone(f,end,dur,vol,pan=0,type='sine',at=context.currentTime,bus=fxBus,attack=.004){const o=context.createOscillator();o.type=type;o.frequency.setValueAtTime(f,at);if(end!==f)o.frequency.exponentialRampToValueAtTime(Math.max(20,end),at+dur);envelope(o,at,dur,vol,pan,bus,attack)}
function noise(dur,vol,pan=0,hz=1800,type='lowpass',at=context.currentTime){const src=context.createBufferSource(),filter=context.createBiquadFilter(),g=context.createGain();src.buffer=noiseBuffer;filter.type=type;filter.frequency.value=hz;filter.Q.value=.7;src.connect(filter);g.gain.setValueAtTime(Math.max(.001,vol),at);g.gain.exponentialRampToValueAtTime(.0001,at+dur);filter.connect(g);const p=context.createStereoPanner?.();if(p){p.pan.value=pan;g.connect(p);p.connect(fxBus)}else g.connect(fxBus);src.onended=()=>{src.disconnect();filter.disconnect();g.disconnect();p?.disconnect()};src.start(at,Math.random()*.35);src.stop(at+dur)}
function metal(at,pan=0,scale=1){noise(.055,.22*scale,pan,3400,'highpass',at);for(const [f,v,d]of [[950,.085,.25],[1479,.063,.36],[2201,.039,.17],[3220,.025,.12]])tone(f*(.96+Math.random()*.08),f,.08+d,v*scale,pan,'sine',at)}
function hammer(at,pan=0){noise(.07,.22,pan,850,'bandpass',at);tone(195,91,.11,.22,pan,'triangle',at);tone(410,210,.055,.075,pan,'sine',at+.012)}
function bell(f,at,vol=.12){for(const [ratio,gain,life]of [[1,1,1.5],[2.76,.38,.9],[5.4,.12,.5]])tone(f*ratio,f*ratio,life,vol*gain,0,'sine',at)}
function completion(kind,at){const dock=['dock','shipyard','bath'].includes(kind),fort=['fort','tower','coastbattery'].includes(kind);bell(dock?660:fort?294:523,at,.12);const notes=dock?[62,69,74,78]:fort?[50,57,62,65]:[62,65,69,74];notes.forEach((n,i)=>pluck(n,at+i*.14,1.35,.34,fxBus));noise(.15,.055,0,1600,'lowpass',at)}
function pluck(midi,at,duration=1.6,volume=.3,bus=musicBus){const key=midi+'-'+duration;let buffer=cache.get(key);if(!buffer){const f=440*2**((midi-69)/12),period=Math.round(context.sampleRate/f),length=Math.ceil(context.sampleRate*duration),data=new Float32Array(length);let seed=midi*117+17;for(let i=0;i<period;i++){seed=(seed*16807)%2147483647;data[i]=(seed/2147483647*2-1)*.7}for(let i=period;i<length;i++)data[i]=.496*(data[i-period]+data[i-period+1]);buffer=context.createBuffer(1,length,context.sampleRate);buffer.copyToChannel(data,0);if(cache.size>60)cache.clear();cache.set(key,buffer)}const src=context.createBufferSource();src.buffer=buffer;envelope(src,at,duration,volume,-.22,bus,.003)}
// Long overlapping modal strings and sparse breathy flute: no background percussion or arpeggio.
const modes=[[50,57,62,65],[48,55,60,64],[43,50,57,62],[45,52,57,60],[41,48,53,57],[50,57,64,69]];
function schedule(){if(!context||context.state!=='running')return;levels();const now=context.currentTime;if(nextNote<now-.4)nextNote=now+.1;if(nextNote>now+.3)return;const section=Math.floor(step/8)%6,phrase=step%8,chord=modes[(section+Math.floor(step/48))%modes.length],at=nextNote; if(musicEnabled&&!document.hidden){const root=440*2**((chord[0]-69)/12);tone(root,root,11.5,.11,-.2,'sine',at,musicBus,1.8);tone(root*2,root*2,10.8,.028,.15,'sine',at,musicBus,2.2);const fifth=440*2**((chord[1]-69)/12);tone(fifth,fifth,12,.045,.2,'sine',at+.2,musicBus,2.1);if(phrase%2===0){const mid=440*2**((chord[2]+(section%2?0:12)-69)/12);tone(mid,mid,9,.023,-.15,'sine',at+.6,musicBus,1.7)}if(phrase%3===1&&Math.random()>.25){const midi=chord[2+(Math.floor(step/3)%2)]+12,f=440*2**((midi-69)/12);tone(f,f,7,.024,.25,'sine',at+1,musicBus,1.2);tone(f*2,f*2,6,.003,.25,'sine',at+1.1,musicBus,1.5)}}nextNote+=6+(step%7===5?2:0);step++;}
A.sound=(kind,pan=0)=>{if(!context||muted||context.state!=='running')return;const at=context.currentTime,interval=['hammer','chop','mine','harvest'].includes(kind)?.16:.065;if(at-(recent[kind]??-10)<interval)return;recent[kind]=at;if(['hammer','melee','musket','cannon','warning','raidWarning','dragonFire'].includes(kind)){duckUntil=at+2.3;levels()}
if(kind==='warning'||kind==='raidWarning'){tone(220,220,.9,.14,pan,'triangle',at);tone(294,294,1,.09,pan,'sine',at+.18)}else if(kind==='dragonFire'){noise(1.1,.44,pan,1050,'lowpass',at);tone(70,37,.8,.28,pan,'sine',at)}else if(kind==='bossClaw'){metal(at,pan,1.1);tone(100,45,.22,.2,pan,'triangle',at)}else if(kind==='magic'){bell(660,at,.065);tone(330,660,1.2,.08,pan,'sine',at)}else if(kind==='melee')metal(at,pan);
else if(kind==='musket'){noise(.12,.55,pan,3700,'lowpass',at);tone(170,48,.23,.26,pan,'triangle',at);noise(.32,.12,pan,1100,'lowpass',at+.04)}
else if(kind==='cannon'||kind==='collapse'){noise(.65,.6,pan,900,'lowpass',at);tone(84,25,.8,.47,pan,'sine',at);noise(.15,.32,pan,3400,'bandpass',at);noise(.8,.12,pan,480,'lowpass',at+.12)}
else if(kind==='grenade'){noise(.4,.4,pan,1700,'lowpass',at);tone(115,34,.4,.3,pan,'sine',at)}
else if(kind==='arrow'){noise(.13,.14,pan,3300,'bandpass',at);pluck(76,at,.13,.2,fxBus)}
else if(kind==='hammer'||kind==='build')hammer(at,pan);
else if(kind==='chop'){hammer(at,pan);noise(.13,.055,pan,1900,'highpass',at+.035)}
else if(kind==='mine')metal(at,pan,.55);
else if(kind==='harvest')noise(.16,.1,pan,1700,'bandpass',at);
else if(kind.startsWith('complete-'))completion(kind.slice(9),at);
else if(kind==='ready'){pluck(69,at,.65,.4,fxBus);pluck(74,at+.09,.8,.4,fxBus)}
else if(kind==='upgrade')completion('fort',at);
else if(kind==='heal'){bell(880,at,.06);bell(1100,at+.12,.04)}
else if(kind==='death'){noise(.25,.18,pan,600,'lowpass',at);tone(130,60,.2,.13,pan,'triangle',at)}
else if(kind==='orderAttack'){metal(at,pan,.26);tone(180,130,.09,.08,pan,'triangle',at)}
else if(kind==='orderGather'){pluck(62,at,.22,.25,fxBus);pluck(69,at+.07,.3,.2,fxBus)}
else if(kind==='invalid')tone(160,110,.13,.09,pan,'triangle',at);
else{noise(.045,.08,pan,700,'bandpass',at);tone(300,240,.07,.04,pan,'sine',at)}
};
})();
